-- C7 review fixes: a held checkout a manager resolves (`RESOLVED`,
-- `resolvedAt`), and the confirmation read's recheck turn (`recheckedAt`).
--
-- Generated by `prisma migrate dev --create-only` against the local cnc_db,
-- then the hand-written part appended below the line. `prisma migrate diff
-- --from-config-datasource --to-schema prisma/schema.prisma --script`
-- prints an empty migration once this is applied.
--
-- Applied to CNC staging by hand with `migrate deploy` before the merge that
-- needs it, on the founder's go-ahead (docs/conventions.md, Data and
-- migrations). It reads and writes nothing of TAY's.

-- AlterEnum
ALTER TYPE "CheckoutStatus" ADD VALUE 'RESOLVED';

-- AlterTable
ALTER TABLE "Checkout" ADD COLUMN     "recheckedAt" TIMESTAMP(3),
ADD COLUMN     "resolvedAt" TIMESTAMP(3);

-- Hand-written below: what Prisma cannot express.
-- ===========================================================================

-- A resolved checkout records when it was resolved, and only a resolved one
-- does. The status is compared as text: a value added to an enum cannot be
-- used as that enum in the transaction that adds it.
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_resolved_check"
  CHECK (("status"::text = 'RESOLVED') = ("resolvedAt" IS NOT NULL));
